package com.madar.files;
import org.junit.Test;
import static org.junit.Assert.*;
public class WatchPlanTest {
 private static long frame(double second){return Math.round(second*44100);}
 private static void commit(PcmRanges ready,WatchWindows w){ready.add(WatchPlan.frame(w.coreStart),WatchPlan.frame(w.coreEnd));}
 @Test public void startingAtFiftyFourPreparesHistoryBeforeTheSelectedScene(){
  for(boolean cloud:new boolean[]{false,true}){PcmRanges r=new PcmRanges();WatchPlan p=new WatchPlan(54000000,362000000,cloud,r);long cursor=0;int n=0;WatchWindows w;while((w=p.next(frame(54)))!=null){assertEquals(cursor,WatchPlan.frame(w.coreStart));commit(r,w);cursor=WatchPlan.frame(w.coreEnd);assertEquals(cursor,r.endFrom(0));assertTrue(++n<30);}assertEquals(frame(362),cursor);assertEquals(cursor,r.total());}
 }
 @Test public void twoMinutesTwentyPreparesPrefixThenForwardReserve(){PcmRanges r=new PcmRanges();WatchPlan p=new WatchPlan(140000000,600000000,true,r);WatchWindows w=p.next(frame(140));assertEquals(0,w.coreStart);commit(r,w);assertEquals(frame(140),r.endFrom(frame(140)));w=p.next(frame(140));assertEquals(40000000,w.coreStart);commit(r,w);assertEquals(frame(140),r.endFrom(frame(140)));w=p.next(frame(140));assertEquals(100000000,w.coreStart);assertEquals(190000000,w.coreEnd);commit(r,w);assertEquals(frame(190),r.endFrom(0));assertEquals(frame(190),r.endFrom(frame(140)));}
 @Test public void choiceIsRequiredOnlyAfterTwoMinutesThirty(){assertFalse(WatchPlan.needsStartChoice(0));assertFalse(WatchPlan.needsStartChoice(140000));assertFalse(WatchPlan.needsStartChoice(150000));assertTrue(WatchPlan.needsStartChoice(150001));assertTrue(WatchPlan.needsStartChoice(600000));}
 @Test public void farSeekCannotDivertProcessingAndLeaveAPrefixHole(){PcmRanges r=new PcmRanges();WatchPlan p=new WatchPlan(0,600000000,true,r);commit(r,p.next(-1));WatchWindows w=p.next(frame(500));assertEquals(40000000,w.coreStart);assertEquals(100000000,w.coreEnd);commit(r,w);assertEquals(frame(100),r.endFrom(0));assertEquals(frame(500),r.endFrom(frame(500)));}
 @Test public void intervalsMergeButSparseFileHolesNeverBecomeReady(){PcmRanges r=new PcmRanges();r.add(54,94);assertEquals(0,r.endFrom(0));assertEquals(53,r.endFrom(53));assertEquals(94,r.endFrom(54));assertArrayEquals(new long[]{0,54},r.firstGap(0,100));r.add(0,40);assertEquals(40,r.endFrom(0));r.add(40,54);assertEquals(94,r.endFrom(0));r.add(10,80);assertEquals(94,r.total());assertArrayEquals(new long[]{94,100},r.firstGap(0,100));}
 @Test public void arbitrarySeekAndRoundTripSampleBoundariesHaveNoGapsOrDuplicateFrames(){for(long origin:new long[]{0,1000,54001000,632500000}){PcmRanges r=new PcmRanges();long end=origin+123456789;WatchPlan p=new WatchPlan(origin,end,true,r);int n=0;WatchWindows w;while((w=p.next(n%3==0?WatchPlan.frame(origin/2):-1))!=null){long a=WatchPlan.frame(w.coreStart),b=WatchPlan.frame(w.coreEnd);assertEquals(a,WatchPlan.frame(WatchPlan.micros(a)));assertEquals(b,WatchPlan.frame(WatchPlan.micros(b)));assertArrayEquals(new long[]{a,b},r.firstGap(a,b));commit(r,w);assertTrue(++n<50);}assertNull(r.firstGap(0,WatchPlan.frame(end)));assertEquals(WatchPlan.frame(end),r.total());}}
 @Test public void shortAudioTailCanFinishWithoutAnInfiniteFinalWindow(){PcmRanges r=new PcmRanges();WatchPlan p=new WatchPlan(54000000,65000000,true,r);commit(r,p.next(-1));WatchWindows w=p.next(-1);assertEquals(65000000,w.coreEnd);r.add(WatchPlan.frame(w.coreStart),frame(64.97));p.trimEnd(frame(64.97));assertNull(p.next(-1));assertEquals(frame(64.97),r.total());}
 @Test public void prefixKeepsFutureContextAcrossAlreadyPreparedBoundary(){PcmRanges r=new PcmRanges();r.add(frame(54),frame(94));WatchPlan p=new WatchPlan(54000000,362000000,true,r);commit(r,p.next(-1));WatchWindows bridge=p.next(frame(54));assertEquals(40000000,bridge.coreStart);assertEquals(54000000,bridge.coreEnd);assertEquals(36000000,bridge.decodeStart);assertEquals(58000000,bridge.decodeEnd);}
}
